"kind": "propose",
"summary": "Liveness probe timeout is too short, causing premature termination of the app during startup.",
"hypotheses": [
  {
    "root_cause_class": "probe_timeout_too_short",
    "summary": "The liveness probe's timeout is 2s, but the app takes longer to respond, leading to timeouts and restarts.",
    "supporting": ["probe_kills", "killed_during_startup", "ev-target_events"],
    "contradicting": ["probe_timeouts"],
