    "status": "supported"
  },
  {
    "root_cause_class": "insufficient_evidence",
    "summary": "No logs confirm the app's behavior during probe failures, making it hard to verify if the app is ready.",
    "supporting": ["container_logs_tail"],
    "contradicting": [],
    "missing": ["container_logs_tail"],
    "status": "supported"
  }
],
"proposal": {
  "capability": "deployment.set-probes",
  "target": {
    "group": "apps",
    "kind": "Deployment",
    "namespace": "payments",
    "name": "payments-worker",
    "uid": "uid-deployment-payments-worker"
  },
  "params": {
    "container": "app",
    "liveness": {
      "timeoutSeconds": 5
    }
  },
  "expected_effect": "Increases the liveness probe timeout to 5s, allowing the app more time to respond before being killed.",
  "rationale": "The liveness probe's timeout of 2s is too short for the app to respond, leading to premature termination. Increasing it to 5s aligns with the app's startup time of 46s and prevents probe timeouts.",
  "cited_evidence_ids": ["ev-rollout_history", "ev-target_events", "ev-pod_states"],
  "cited_predicates": ["probe_kills", "killed_during_startup", "crashed_on_its_own"]
}
}
